// Determine the path to the first recorded example of `modelType`.
func mustFirstExpectedPath(t *testing.T, modelType string) string {
	pths := ourtesting.FindFilesBySuffixRecursively(
		filepath.Join(
			ourtesting.TestDataDir,
			"Json",
			"Expected",
			modelType,
		),
		".json",
	)
	sort.Strings(pths)

	if len(pths) == 0 {
		t.Fatalf(
			"Expected at least one recorded example of %s, but got none",
			modelType,
		)
	}

	return pths[0]
}

// Assert that `that` can not be serialized to JSON, and that the failure
// is reported at `expectedPath`.
func assertSerializationFailsAt(
	t *testing.T,
	that ourtypes.IClass,
	expectedPath string,
) {
	_, err := ourjsonization.ToJsonable(that)

	if err == nil {
		t.Fatalf(
			"Expected the serialization to fail at %s, but it succeeded",
			expectedPath,
		)
		return
	}

	seriaErr, ok := err.(*ourjsonization.SerializationError)
	if !ok {
		t.Fatalf(
			"Expected a *SerializationError, but got %T: %v",
			err, err,
		)
		return
	}

	if seriaErr.PathString() != expectedPath {
		t.Fatalf(
			"Expected the serialization to fail at %s, "+
				"but it failed at %s: %s",
			expectedPath, seriaErr.PathString(), seriaErr.Message,
		)
	}
}

func TestSomethingRoundTripOK(t *testing.T) {
	pths := ourtesting.FindFilesBySuffixRecursively(
		filepath.Join(
			ourtesting.TestDataDir,
			"Json",
			"Expected",
			"Something",
		),
		".json",
	)
	sort.Strings(pths)

	for _, pth := range pths {
		jsonable := ourtesting.MustReadJsonable(
			pth,
		)

		deserialized, deseriaErr := ourjsonization.SomethingFromJsonable(
			jsonable,
		)
		ok := assertNoDeserializationError(t, deseriaErr, pth)
		if !ok {
			return
		}

		anotherJsonable, seriaErr := ourjsonization.ToJsonable(deserialized)
		ok = assertNoSerializationError(t, seriaErr, pth)
		if !ok {
			return
		}

		ok = assertSerializationEqualsDeserialization(
			t,
			jsonable,
			anotherJsonable,
			pth,
		)
		if !ok {
			return
		}
	}
}

func TestSomethingDeserializationFail(t *testing.T) {
	pattern := filepath.Join(
		ourtesting.TestDataDir,
		"Json",
		"Unexpected",
		"Unserializable",
		"*",  // This asterisk represents the cause.
		"Something",
	)

	causeDirs, err := filepath.Glob(pattern)
	if err != nil {
		panic(
			fmt.Sprintf(
				"Failed to find cause directories matching %s: %s",
				pattern, err.Error(),
			),
		)
	}

	for _, causeDir := range causeDirs {
		pths := ourtesting.FindFilesBySuffixRecursively(
			causeDir,
			".json",
		)
		sort.Strings(pths)

		for _, pth := range pths {
			jsonable := ourtesting.MustReadJsonable(
				pth,
			)

			relPth, err := filepath.Rel(ourtesting.TestDataDir, pth)
			if err != nil {
				panic(
					fmt.Sprintf(
						"Failed to compute the relative path of %s to %s: %s",
						ourtesting.TestDataDir, pth, err.Error(),
					),
				)
			}

			expectedPth := filepath.Join(
				ourtesting.TestDataDir,
				"DeserializationError",
				filepath.Dir(relPth),
				filepath.Base(relPth)+".error",
			)

			_, deseriaErr := ourjsonization.SomethingFromJsonable(
				jsonable,
			)
			ok := assertDeserializationErrorEqualsExpectedOrRecord(
				t, deseriaErr, pth, expectedPth,
			)
			if !ok {
				return
			}
		}
	}
}

func TestSomethingSerializationFailOnOutOfRangeNumber(t *testing.T) {
	pth := mustFirstExpectedPath(t, "Something")

	for _, value := range []int64{
		9007199254740992,
		-9007199254740992,
	} {
		jsonable := ourtesting.MustReadJsonable(pth)

		instance, deseriaErr := ourjsonization.SomethingFromJsonable(
			jsonable,
		)
		if !assertNoDeserializationError(t, deseriaErr, pth) {
			return
		}

		instance.SetNumber(value)

		assertSerializationFailsAt(
			t,
			instance,
			"Number()",
		)
	}
}

